from zscaler.zpa.application_segment import ApplicationSegmentAPI

SEGMENT_ID = "<id>"
CONFIG = {"client": {"customerId": "<id>"}}


class StubResponse:
    def get_body(self):
        return {}          # what a 204 yields

    def get_results(self):
        return []

    def get_status(self):
        return 204


class StubExecutor:
    """Stands in for RequestExecutor."""

    def create_request(self, method, endpoint, body=None, headers=None, params=None,
                       use_raw_data_for_body=False):
        return {"method": method, "endpoint": endpoint.strip(),
                "body": {} if body is None else body, "params": params or {}}, None

    def execute(self, request, response_type=None, return_raw_response=False):
        return StubResponse(), None


seg, resp, err = ApplicationSegmentAPI(StubExecutor(), CONFIG).update_segment(
    SEGMENT_ID, description="new description")

print("err            =", err)
print("type           =", type(seg).__name__)
print("seg.enabled    =", seg.enabled, "  <- never sent by the API")
print("seg.domain_names =", seg.domain_names, "  <- never sent by the API")
print("as_dict()      =", seg.as_dict())
